<?php
namespace Tests\Feature; use App\Models\{Product,PurchaseOrder,Supplier,User,Warehouse}; use App\Services\PurchaseManagementService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class PurchaseManagementProTest extends TestCase { use RefreshDatabase; public function test_partial_grn_updates_stock_and_po_status():void { $user=User::factory()->create(); $supplier=Supplier::create(['name'=>'Supplier','phone'=>'01700000001','status'=>true]); $warehouse=Warehouse::create(['name'=>'Main','code'=>'MAIN','status'=>true,'created_by'=>$user->id]); $product=Product::factory()->create(['stock_quantity'=>0]); $service=app(PurchaseManagementService::class); $po=$service->createOrder(['po_number'=>'PO-TEST','supplier_id'=>$supplier->id,'warehouse_id'=>$warehouse->id,'order_date'=>now()->toDateString(),'discount'=>0,'tax'=>0,'shipping'=>0,'items'=>[['product_id'=>$product->id,'ordered_quantity'=>10,'unit_price'=>100]]],$user->id); $service->approveOrder($po,$user->id); $service->receive($po,['grn_number'=>'GRN-TEST','warehouse_id'=>$warehouse->id,'received_date'=>now()->toDateString(),'items'=>[['purchase_order_item_id'=>$po->items->first()->id,'quantity'=>4]]],$user->id); $this->assertSame(4,$product->fresh()->stock_quantity); $this->assertSame('partially_received',$po->fresh()->status); } }
